      "arabic": "وَلٰكِنَّا كُنَّا نَرْجُو الْغَيْثَ وَالْفَرَجَ،",
      "urdu": "لیکن اس تمام تر عسرت کے باوجود ہم اللہ سے بارش اور کشادگی کی امید لگائے ہوئے تھے،"
