      "urdu": "پس میں اپنی اسی کمزور گدھی پر سوار چلی، تو اس کی سست رفتاری، کمزوری اور لاغری کی وجہ سے میں نے پورے قافلے کو تھکا دیا یہاں تک کہ ان کا میرے ساتھ چلنا وبالِ جان بن گیا،"
