      "urdu": "پس ہم میں سے کوئی ایک عورت بھی ایسی نہ تھی جس کے سامنے رسول اللہ ﷺ کو پیش نہ کیا گیا ہو، مگر جب بھی اسے بتایا جاتا کہ یہ بچہ یتیم ہے تو وہ اسے گود لینے سے انکار کر دیتی،"
