        urdu: 'حضرت عائشہ رضی اللہ عنہا جو نبی اکرم صلی اللہ علیہ وسلم کی زوجہ ہیں فرماتی ہیں کہ جب سے میں ہوش سنبھالا میں نے اپنے والدین کو دین اسلام پر ہی پایا'
