        urdu: 'وہاں قارہ ابن الدغنہ سے ملاقات ہوئی، وہ قبیلہ قارہ کے سردار تھے، اس نے پوچھا: اے ابوبکر کہاں کا ارادہ ہے؟ تو ابوبکر رضی اللہ عنہ نے بتایا کہ'
