        urdu: 'تو قریش نے ابن الدغنہ کی پناہ کا انکار نہیں کر سکے اور ابن الدغنہ سے کہا کہ ابوبکر سے کہو کہ وہ اپنے گھر میں اپنے رب کی عبادت کرسکتا ہے،'
