        urdu: 'میرے ساتھ مسلسل یوں ہی ہوتا رہا، حتی کہ وہ تیز ہوگئے اور غزوہ مجھ سے فوت ہو گیا، اس وقت بھی خیال آیا کہ نکل پڑوں اور لشکر سے جاملوں'
