        urdu: 'عمرو بن میمون بیٹھ فرماتے ہیں کہ (جس صبح حضرت عمر پر مصیبت آئی) میں (نماز کے انتظار میں صف میں) کھڑا تھا، میرے اور آپ (حضرت عمر بیٹھ کے) کے درمیان عبداللہ بن عباس رضی اللہ عنہم کے علاوہ کوئی نہیں تھا۔'
