        urdu: 'جو حضرت عمر رضی اللہ عنہ کے قریب تھے انہوں نے وہ کچھ دیکھا جو میں نے دیکھا، باقی جو لوگ مسجد کے اطراف میں تھے انہیں اس کے سوا کچھ معلوم نہیں ہوسکا'
