        urdu: 'اتنی بڑی مصیبت اس دن سے پہلے نہ پہنچی ہو، کوئی کہتا: کہ کچھ نہیں ہوگا، کوئی کہتا: کہ مجھے ان پر خطرہ ہے۔ پھر کھجور کا پانی لایا گیا'
