        urdu: '. آپ نے پیا تو وہ پیٹ سے باہر نکل آیا، پھر دودھ پیش کیا گیا، اسے پیا تو وہ بھی پیٹ سے باہر آ گیا، لوگ سمجھ گئے کہ آپ شہید ہو جائیں گے۔'
