        urdu: 'آپ نے اپنے آپ پر خاموشی لازم کر لی، حتی کہ اسے انصاف پر لاکھڑا کیا، آپ نے نفس کی توہین کی حالانکہ آپ اس کی عزت چاہتے تھے۔'
