      {
        label: '4',
        arabic: '',
        urdu: '”اے میری محترم امی جان! آپ کا گرامی نامہ موصول ہوا۔ اللہ آپ کو اپنی امان میں رکھے اور نگہبانی کے ساتھ آپ کی سرپرستی فرمائے۔ میں نے خط کا حرف بہ حرف مطالعہ کیا، اور اللہ گواہ ہے کہ جو کچھ آپ نے اس میں بیان فرمایا ہے اس نے مجھے دل کی گہرائیوں سے غمگین و رنجیدہ کر دیا ہے۔\nلیکن الٰہی تقدیریں نافذ ہو کر رہتی ہیں، احکام جاری و ساری ہیں، اور معاملات الٹ پلٹ ہوتے رہتے ہیں؛ ساری مخلوق اللہ کے قبضۂ قدرت میں ہے، وہ اس کی قضا کو ٹالنے پر قادر نہیں ہے۔ اور یہ پوری دنیا فنا اور زوال کی طرف جانے والی ہے، اور ہر جاندار کو موت کا مزہ چکھنا ہے۔ بدعہدی اور فریب انسان کی موت کا سامان ہیں، اور مکر کا انجام مکر کرنے والے ہی کی طرف لوٹتا ہے۔\nمیں نے آپ کی چھینی گئی تمام جائیداد اور سامان واپس کرنے کا حکم جاری کر دیا ہے؛ اور جو شخص اللہ کی رحمت کی طرف رخصت ہو چکا (محمد الامین) آپ نے اس کے چہرے کے سوا اور کچھ نہیں کھویا (یعنی میں آپ کے سگے بیٹے کی طرح حاضر ہوں)، اور اس کے بعد بھی میں آپ کی توقعات اور پسند سے بڑھ کر خدمت کے لیے تیار ہوں، والسلام!“'
      }
