        urdu: 'اور ان کے پڑھنے کی، چنانچہ بغیر رات ان جملہ خبروں، سیر و آثار اور سیاسیات کی انواع کو سنتے سنتے گزر جاتی تھی، پھر آپ رضی اللہ عنہ نکلتے'
