        urdu: 'انہوں نے اپنی پشت سے کپڑا ہٹایا، مجھے وہاں سوائے مار کے نشان کے کچھ بھی دکھائی نہ دیا۔ میں نے کہا : مجھے اس بارے میں زیادہ علم نہیں، لیکن میں اس بارے میں معلومات کروں گا'
