        urdu: 'میں جیل میں ایک ضرورت کی وجہ سے جانا چاہتا ہوں؟ اس نے کہا : چلے جاؤ، میں اندر گیا ، اور وہاں کے نوجوانوں کو جمع کیا، اس حال میں کہ میرے پاس کچھ دراہم تھے'
