        urdu: 'وہ میں نے ان میں تقسیم کر دیئے اور میں ان سے باتیں کرنے لگا یہاں تک کہ وہ مجھ سے مانوس ہو گئے۔ پھر میں نے پوچھا : تم میں سے'
