        urdu: 'زیادہ کسے مار پڑی ہے؟ اور شاعر ہوتے ہوئے ایک دوسرے پر فخر کرنے لگے ، یہاں تک کہ انہوں نے ایک پر سب نے اتفاق کیا کہ یہ سب سے زیادہ سخت مارنے والا اور سب سے زیادہ صبر میں ڈالنے والا ہے'
