        urdu: 'تو میں نے اس سے کہا : میں تم سے ایک بات پوچھوں؟ اس نے کہا : ہاں ہاں پوچھو! میں نے کہا : ایک کمزور بوڑھا، جس کا کام تمہاری طرح کا نہیں'
