        urdu: 'اسے قتل کرنے کے لیے بھوک کی حالت میں چند کوڑے مارے گئے ، مگر یہ کہ وہ نہیں مرا، انہوں نے علاج کیا اور وہ ٹھیک ہو گیا، مگر'
