        urdu: 'اس کی پیٹھ میں ایک جگہ ایسی رہ گئی ہے، جو درد کر رہی ہے، وہ اس کو برداشت نہیں کر پاتا۔ کہتے ہیں کہ وہ زور سے ہنس پڑا، میں نے پوچھا: تجھے کیا ہوا؟'
