        urdu: 'تو اس نے کہا: جس نے اس کا علاج کیا تھا وہ ایک جولا ہا تھا۔ میں نے کہا: یہ کیا کہہ رہے ہو؟ اس نے کہا : اصل میں بات یہ ہے کہ اس نے مردار گوشت کا ٹکڑا اس کی پیٹھ میں چھوڑ دیا تھا،'
