        urdu: 'میں نے سارا قصہ بتایا، انہوں نے پوچھا : کون اس زخم کو چیرے گا؟ میں نے کہا کہ : میں، انہوں نے کہا : کیا تو یہ کام کر لے گا ، میں نے کہا : جی ہاں، چنانچہ وہ اٹھے'
