        urdu: 'اور گھر چلے گئے، واپس لوٹے تو ان کے ہاتھ میں دو تکیے اور کندھے پر ایک رومال تھا، ان میں سے ایک میرے لیے رکھا اور دوسرا اپنے لیے'
