        urdu: 'تو دیکھا کہ میں اس تدریس میں بھی ایسے دقیق علوم میں الجھا ہوا ہوں جو نہ تو بذاتِ خود اہم ہیں اور نہ ہی آخرت کی نجات کے راستے میں نفع بخش ہیں،'
