        urdu: 'تو مجھے قطعی یقین ہو گیا کہ میں ایک گرنے والی کھائی کے دہانے پر کھڑا ہوں، اور اگر میں نے اپنے احوال کی تلافی و اصلاح نہ کی تو میں جہنم کے کنارے پہنچ چکا ہوں،'
