        urdu: 'ایک دن میں بغداد کی اس علمی مسند کو چھوڑ کر نکل جانے کا پکا ارادہ کرتا، اور دوسرے دن دنیاوی مصلحتوں کی وجہ سے اپنا ارادہ توڑ دیتا،'
