        urdu: 'اور مخالفین کے جھگڑوں سے محفوظ یہ مسلمہ اقتدار تم نے گنوا دیا، تو بعد میں تمہارا نفس دوبارہ اس کی طرف للچائے گا اور اس وقت تمہارے لیے اس مسند پر واپسی ناممکن ہو جائے گی!“'
