        urdu: 'اور (آپ استقلال کے ایسے پہاڑ تھے کہ) جب آپ نہ کہہ دیتے تو لوگ ہاں نہیں کہلو اسکتے تھے۔ تو انہوں نے کہا: دوسری بات یہ ہے کہ آپ اپنے گھر میں بیٹھے رہیں، چند دن تک نماز کے لیے نہ نکلیں'
