        urdu: 'کیونکہ یہ بات بھی انہیں قبول ہے کہ جب آپ کو مجلس میں بلانا چاہیں گے تو آپ کو نہیں پائیں گے۔ فرمایا: میں کانوں سے اذان سنوں اور اسے کانوں کے اوپر سے گزار دوں'
