        arabic: 'حَيَّ عَلَى الصَّلَاةِ حَيَّ عَلَى الصَّلَاةِ، مَا أَنَا بِفَاعِلٍ، قَالُوا: فَانْتَقِلْ مِنْ مَجْلِسِكَ إِلَى غَيْرِهِ، فَإِنَّهُ',
