        urdu: 'آپ کی مجلس کی طرف آدمی بھیجے گا اور آپ نہیں ملیں گے تو وہ آپ سے رک جائے گا۔ فرمایا: کیا مخلوق کے ڈر سے ایسا کروں؟'
