        urdu: 'تو اس نے حکم دیا کہ کپڑے اتار دیے جائیں، دیکھا کہ آپ کے اوپر بالوں کا لباس تھا، تو والی کہنے لگا: اگر تجھے اس کا علم ہوتا تو آپ کو اس طرح مشہور نہ کیا جاتا'
