        urdu: 'جان لو! لوگوں پر ان کے اموال کے معاملے میں ظلم کرنا ان کے مال حاصل کرنے اور کمانے کی امید کو ختم کر دیتا ہے؛ اس لیے کہ وہ دیکھ رہے ہوتے ہیں کہ ان کی کمائی کی انتہاء اور انجام ان کے ہاتھوں سے چھن جانا ہے، اور جب مال کے حاصل کرنے اور کمانے میں ان کی تمنائیں ختم ہو جائیں تو اس کے لیے محنت اور کوشش کرنے سے ان کے ہاتھ کھنچ جاتے ہیں، اور ان لوگوں کا کسب و کمائی سے دلچسپی کا ختم ہو جانا ظلم و زیادتی کے بقدر و زیادتی کے اعتبار سے ہوتا ہے۔'
