        urdu: 'چنانچہ جب ظلم و زیادتی ذریعہ معاش کے تمام ذرائع میں بہت زیادہ عام ہوگی تو کسب و کمائی سے اعراض بھی اسی تناسب سے ہوگا اس لیے کہ ظلم، معاش کے تمام دروازوں میں داخل ہو کر تمام امیدوں پر پانی پھیر دیتا ہے، اور اگر ظلم کم ہو تو لوگوں کا کمائی سے ہاتھ کترانا بھی اسی تناسب سے ہوگا۔'
