        urdu: 'آبادی اور اس کی کثرت اور گرم بازاری یہ چیزیں کام کرنے سے اور لوگوں کے مصالح اور کمائی کے ذرائع میں کوشش کرنے کے لیے آنے جانے سے ہوتی ہے۔'
