        urdu: 'اور لوگ رزق کی تلاش میں اس صوبے کے علاوہ دنیا کے اطراف میں بکھر جاتے ہیں، جو حکومتی انتظام سے باہر ہوتے ہیں۔ چنانچہ جب ایک ملک کے رہائشی کوچ کرنے لگتے ہیں،'
