        arabic: 'أَنَا إِنْ كُنْتُ حَاسِدًا أَحَدًا عَلَى نِعْمَةٍ فَإِنِّي أَحْسُدُ صَاحِبَ الْكُوْخِ عَلَى كُوْخِهِ، قَبْلَ أَنْ أَحْسُدَ صَاحِبَ الْقَصْرِ عَلَى قَصْرِهِ، وَلَوْلَا أَنَّ لِلْأَوْهَامِ سُلْطَانًا عَلَى النُّفُوْسِ لَمَا تَضَاءَلَ الْفُقَرَاءُ بَيْنَ أَيْدِي الْأَغْنِيَاءِ وَلَا وَرِمَ أَنْفُ الْأَغْنِيَاءِ أَنْ يَتِّخِذَهُمُ الْفُقَرَاءُ أَرْبَابًا مِنْ دُوْنِ اللهِ. أَنَا لَا أَغْبِطُ الْغَنِيَّ إِلَّا فِي مَوْطِنٍ وَاحِدٍ مِنْ مَوَاطِنِهِ، إِنْ رَأَيْتُهُ يُشْبِعُ الْجَائِعَ، وَيُوَاسِي الْفَقِيْرَ، وَيَعُوْدُ بِالْفَضْلِ مِنْ مَالِهِ عَلَى الْيَتِيْمِ الَّذِي سَلَبَهُ الدَّهْرُ أَبَاهُ، وَالْأَرْمَلَةِ الَّتِي فَجَعَهَا الْقَدْرُ فِي عَائِلِهَا، وَيَمْسَحُ بِيَدِهِ دَمْعَةَ الْبَائِسِ وَالْمَحْزُوْنِ',
        urdu: 'میں اگر کسی کی نعمت پر حسد کرنے والا ہوتا تو جھونپڑی والے کی جھونپڑی پر حسد کرتا، محل والے کے محل پر حسد کرنے سے پہلے، اور اگر توہمات نفس پر غالب نہ ہوتے تو فقیر لوگ امیروں کے سامنے ذلیل نہ ہوتے اور نہ دولت مندوں کا ناک پھولتا اس سے کہ فقراء لوگ انہیں اللہ کے علاوہ پالنے والا سمجھتے ہیں۔ میں مالدار آدمی پر رشک نہیں کرتا مگر اس کی زندگی کے تمام مراحل میں سے ایک مرحلے پر، اگر میں اسے دیکھوں کہ وہ بھوکے کو کھانا کھلا رہا ہے، فقیر کی دلجوئی کر رہا ہے، اور فضل کا معاملہ کر رہا ہے اپنے مال کے ذریعے اس یتیم پر، زمانے نے جس کے باپ کو چھین لیا ہے، اور اس بیوہ عورت پر (فضل کا معاملہ کر رہا ہے) جس کو تقدیر نے معاشی تنگی میں مبتلا کر رکھا ہے، اور اپنے ہاتھ کے ذریعے صاف کر رہا ہے پریشان حال اور غمزدہ لوگوں کے آنسو'
