      urdu: 'جب ابو حذیفہ حضرت عثمانؓ کے گھر پہنچ کر اندر داخل ہوئے تو ان کے باوفا دوست نے حسبِ معمول خندہ پیشانی، دلی مسرت، شفقت اور کمالِ نرمی سے ان کا پرجوش استقبال کیا،'
