      urdu: 'ابو حذیفہ نے حیرت سے پوچھا: ”تو کیا آپ نے اپنی قوم میں کوئی خرابی دیکھی ہے جس سے آپ کو نفرت ہو گئی ہے؟“ یہاں حضرت عثمانؓ خاموش ہو گئے اور کوئی جواب نہ دیا، ابو حذیفہ نے اپنا سوال دہرایا مگر حضرت عثمانؓ نے گہری خاموشی اختیار فرمائی!'
