      urdu: 'حضرت عثمانؓ نے کمالِ نرمی اور متانت بھرے لہجے میں فرمایا: ”اگر تم ہمارے درمیان پرانی محبت اور دوستی کو باقی رکھنا چاہتے ہو تو آئندہ میرے سامنے لات اور عزیٰ اور ان بے بس پتھر کے بتوں کا نام نہ لینا جو تمہیں ذرہ برابر کوئی نفع یا نقصان نہیں پہنچا سکتے!“'
