      urdu: 'اور کہانی کا آغاز سنتے ہی پورا واقعہ ان کے ذہنوں میں تازہ ہو جاتا، اور ان کی آنکھوں کے سامنے وہ مفلوک الحال، لاغر لڑکا گھوم جاتا جسے مصیبتوں نے توڑا تھا، جس سے عرب اور یہودی سب نے منہ موڑ لیا تھا اور جسے ثبیتہ بنت یعار نے کسی فائدے کے لیے نہیں بلکہ محض ترس کھا کر خریدا تھا!'
